function loadKey(keyId: string): Buffer | null {
  if (!ACTIVE_ROSTER.has(keyId)) {
    return null;
  }
  try {
    const data = readFileSync(`${KEY_DIR}/${keyId}.key`);
    return data.slice(0, -1); // strip trailing newline
  } catch {
    return null;
